<?php
/** Immutable normalized payment-event receipt ready for one-statement persistence. @package CPT2Collection */
declare( strict_types=1 );
namespace RodolfoRizzo\Cpt2Collection;
use InvalidArgumentException;
defined( 'ABSPATH' ) || exit;

final class PaymentEventReceipt {
	private string $provider; private string $provider_event_id; private string $event_type; private ?string $provider_created_at; private bool $livemode; private ?string $provider_session_id; private ?string $local_reference; private ?string $provider_payment_id; private ?string $currency; private ?int $amount_minor; private ?string $payment_status; private ?string $session_status; private string $payload_sha256; private ?string $normalized_payload;
	public function __construct( string $provider, string $provider_event_id, string $event_type, ?string $provider_created_at, bool $livemode, ?string $provider_session_id, ?string $local_reference, ?string $provider_payment_id, ?string $currency, ?int $amount_minor, ?string $payment_status, ?string $session_status, string $payload_sha256, ?string $normalized_payload ) {
		if ( 1 !== preg_match( '/\A[a-z0-9_]{1,32}\z/', $provider ) || '' === trim( $provider_event_id ) || strlen( $provider_event_id ) > 255 || '' === trim( $event_type ) || strlen( $event_type ) > 128 || 1 !== preg_match( '/\A[0-9a-f]{64}\z/', $payload_sha256 ) || ( null !== $local_reference && 1 !== preg_match( '/\A[0-9a-f]{32}\z/', $local_reference ) ) || ( null !== $currency && ! isset( Money::get_currencies()[ $currency ] ) ) || ( null !== $amount_minor && $amount_minor < 0 ) || ( null !== $normalized_payload && ( strlen( $normalized_payload ) > 65535 || ! is_array( json_decode( $normalized_payload, true ) ) || JSON_ERROR_NONE !== json_last_error() ) ) ) { throw new InvalidArgumentException( 'Normalized payment receipt is invalid.' ); }
		foreach ( array( array( $provider_session_id, 255 ), array( $provider_payment_id, 255 ), array( $payment_status, 32 ), array( $session_status, 32 ) ) as $value ) { if ( null !== $value[0] && ( '' === trim( $value[0] ) || strlen( $value[0] ) > $value[1] ) ) { throw new InvalidArgumentException( 'Normalized payment receipt is invalid.' ); } }
		$this->provider=$provider; $this->provider_event_id=$provider_event_id; $this->event_type=$event_type; $this->provider_created_at=$provider_created_at; $this->livemode=$livemode; $this->provider_session_id=$provider_session_id; $this->local_reference=$local_reference; $this->provider_payment_id=$provider_payment_id; $this->currency=$currency; $this->amount_minor=$amount_minor; $this->payment_status=$payment_status; $this->session_status=$session_status; $this->payload_sha256=$payload_sha256; $this->normalized_payload=$normalized_payload;
	}
	public function provider():string{return $this->provider;} public function provider_event_id():string{return $this->provider_event_id;} public function event_type():string{return $this->event_type;} public function provider_created_at():?string{return $this->provider_created_at;} public function livemode():bool{return $this->livemode;} public function provider_session_id():?string{return $this->provider_session_id;} public function local_reference():?string{return $this->local_reference;} public function provider_payment_id():?string{return $this->provider_payment_id;} public function currency():?string{return $this->currency;} public function amount_minor():?int{return $this->amount_minor;} public function payment_status():?string{return $this->payment_status;} public function session_status():?string{return $this->session_status;} public function payload_sha256():string{return $this->payload_sha256;} public function normalized_payload():?string{return $this->normalized_payload;}
}
